const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('chordroom-saved',JSON.stringify(saved));$('savedCount').textContent=saved.length}catch{status('저장 공간을 사용할 수 없습니다. 브라우저 저장 설정을 확인해주세요.')}}
function status(s){$('status').textContent=s}
function shift(c,n){return c.replace(/[A-G](?:#|b)?/g,root=>{const flats={Db:'C#',Eb:'D#',Gb:'F#',Ab:'G#',Bb:'A#'};return notes[(notes.indexOf(flats[root]||root)+n+120)%12]})}
function list(){const base=view==='saved'?saved:library;let songs=base.filter(s=>(s.title+' '+s.artist+' '+(s.aliases||'')).toLowerCase().includes(query.toLowerCase()));if(filter==='easy')songs=songs.filter(s=>['grace','arirang','twinkle','auld'].includes(s.id));if(filter==='folk')songs=songs.filter(s=>!s.audio);$('listTitle').textContent=view==='saved'?'다시 연주하고 싶은 곡':query?'“'+query+'” 검색 결과':'어떤 곡을 연주할까요?';$('results').replaceChildren();songs.forEach(s=>card(s));$('resultCount').textContent=songs.length+'곡';if(!songs.length)$('results').innerHTML='<div class="empty">'+(view==='saved'?'아직 저장한 악보가 없어요.<br>악보의 ♡ 저장 버튼으로 나만의 연주 목록을 만드세요.':'수록된 악보가 없습니다.<br>음원 검색 결과를 확인하거나, 내 음원을 올려 코드를 분석해보세요.')+'</div>'}
function card(s,external=false){const b=document.createElement('button');b.className='song-card';b.innerHTML='<div class="cover" style="background:'+(s.color||'#85967b')+'">'+(s.image?'<img src="'+esc(s.image)+'" alt="" loading="lazy">':esc(s.icon||'♫'))+'</div><div class="song-info"><strong>'+esc(s.title)+'</strong><p>'+esc(s.artist)+'</p><span class="badge '+(external?'external':'')+'">'+(external?'음원 검색 · 악보 미등록':s.audio?'오디오 분석 · 추정 코드':s.id==='sun'||s.id==='greensleeves'?'보통 · 연주용 편곡':'쉬움 · 코드악보')+'</span></div><span class="card-arrow">↗</span>';b.onclick=()=>external?externalDialog(s):openSheet(s);$('results').append(b)}
function modal(html){$('dialogBody').innerHTML=html;$('dialog').showModal()}
function externalDialog(s){modal('<div class="eyebrow">SONG DISCOVERY</div><h2>'+esc(s.title)+'</h2><p>'+esc(s.artist)+'</p><p>이 곡의 코드악보는 아직 등록되지 않았습니다. 외부 서비스에서 악보를 찾거나, 직접 가진 음원을 올려 코드를 추정할 수 있습니다.</p><a target="_blank" rel="noopener noreferrer" href="https://chordify.net/search/'+encodeURIComponent(s.title+' '+s.artist)+'">Chordify에서 코드 찾기 ↗</a><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query='+encodeURIComponent(s.title+' '+s.artist)+'">YouTube에서 듣기 ↗</a><p>외부 서비스의 분석·로그인·요금 조건이 적용됩니다.</p><button class="primary" id="dialogUpload">내 음원 분석하기</button>');$('dialogUpload').onclick=()=>{$('dialog').close();$('audioFile').click()}}
function youtubeId(q){try{const u=new URL(q);if(u.hostname==='youtu.be')return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(/(^|\.)(youtube\.com|youtube-nocookie\.com)$/.test(u.hostname)){const id=u.searchParams.get('v')||u.pathname.split('/').filter(Boolean)[1];return /^[\w-]{11}$/.test(id||'')?id:null}}catch{}return null}
async function search(){const seq=++searchSeq;query=$('query').value.trim();view='discover';filter='all';setNav();list();const id=youtubeId(query);if(id){query='';list();modal('<div class="eyebrow">YOUTUBE LINK</div><h2>영상으로 코드 찾기</h2><p>이 앱에서는 유튜브 음원을 직접 가져와 분석하지 않습니다. 외부 코드 검색을 열거나, 보유한 음원 파일을 분석해주세요.</p><iframe width="100%" height="220" style="border:0;border-radius:8px" src="https://www.youtube-nocookie.com/embed/'+id+'" title="YouTube 영상" allowfullscreen></iframe><a target="_blank" rel="noopener noreferrer" href="https://chordify.net/search/'+encodeURIComponent('https://www.youtube.com/watch?v='+id)+'">이 영상의 코드를 Chordify에서 찾기 ↗</a><button class="primary" id="dialogUpload">내 음원 분석</button>');$('dialogUpload').onclick=()=>{$('dialog').close();$('audioFile').click()};return}if(/^https?:/i.test(query)){status('올바른 YouTube 또는 YouTube Music 영상 링크를 입력해주세요.');return}if(!query){status('');return}status('다른 음원도 찾고 있습니다…');try{const songs=await musicSearch(query);if(seq!==searchSeq)return;const existing=Array.from($('results').querySelectorAll('.song-card')).length;if(songs.length){if(!existing)$('results').replaceChildren();songs.forEach(s=>card(s,true));$('resultCount').textContent=(existing+songs.length)+'곡';status('수록곡은 바로 악보를 열 수 있습니다. 일반 음원은 외부 코드 검색 또는 파일 분석을 이용해주세요.')}else status(existing?'수록 코드악보를 찾았습니다.':'검색 결과가 없습니다. 제목·아티스트를 바꾸거나 음원 파일을 올려주세요.')}catch{if(seq===searchSeq)status('외부 음원 검색에 연결하지 못했습니다. 수록곡 검색과 파일 분석은 계속 사용할 수 있습니다.')}}
function musicSearch(term){return new Promise((resolve,reject)=>{const name='crSearch'+Date.now(),script=document.createElement('script');const timer=setTimeout(()=>{cleanup();reject(new Error('timeout'))},10000);function cleanup(){clearTimeout(timer);script.remove();delete window[name]}window[name]=data=>{cleanup();const seen=new Set();resolve((data.results||[]).filter(x=>{const k=x.trackName+' '+x.artistName;if(seen.has(k))return false;seen.add(k);return true}).slice(0,9).map(x=>({title:x.trackName,artist:x.artistName,image:x.artworkUrl100,duration:x.trackTimeMillis/1000})).filter(x=>x.title))};script.onerror=()=>{cleanup();reject(new Error('network'))};script.src='https://itunes.apple.com/search?term='+encodeURIComponent(term)+'&entity=song&country=KR&limit=12&callback='+name;document.head.append(script)})}
const shapes={C:[-1,3,2,0,1,0],Cm:[-1,3,5,5,4,3],D:[-1,-1,0,2,3,2],Dm:[-1,-1,0,2,3,1],E:[0,2,2,1,0,0],Em:[0,2,2,0,0,0],F:[1,3,3,2,1,1],Fm:[1,3,3,1,1,1],G:[3,2,0,0,0,3],Gm:[3,5,5,3,3,3],A:[-1,0,2,2,2,0],Am:[-1,0,2,2,1,0],B:[-1,2,4,4,4,2],Bm:[-1,2,4,4,3,2]};
function diagram(chord){let shape=shapes[chord],base=1;if(!shape){const root=chord.replace(/m$/,'');const fret=(notes.indexOf(root)-4+12)%12;if(fret>=0){shape=(chord.endsWith('m')?[0,2,2,0,0,0]:[0,2,2,1,0,0]).map(x=>x+fret)}}if(!shape)return '';const positives=shape.filter(x=>x>0);if(Math.max(...positives)>4)base=Math.min(...positives);let svg='<svg viewBox="0 0 68 86" role="img" aria-label="'+esc(chord)+' 기타 운지표">';for(let i=0;i<6;i++)svg+='<path d="M '+(10+i*9)+' 20 V 76" stroke="#c8d2bd" stroke-width="1"/>';for(let i=0;i<5;i++)svg+='<path d="M 10 '+(20+i*14)+' H 55" stroke="#b1bfa3" stroke-width="'+(i===0&&base===1?3:1)+'"/>';shape.forEach((f,i)=>{if(f<=0)svg+='<text x="'+(10+i*9)+'" y="13" text-anchor="middle" font-size="10" fill="#75856b">'+(f<0?'×':'○')+'</text>';else svg+='<circle cx="'+(10+i*9)+'" cy="'+(27+(f-base)*14)+'" r="3.7" fill="#2f6651"/>'});if(base>1)svg+='<text x="62" y="30" font-size="7" fill="#75856b">'+base+'</text>';return '<div class="diagram"><b>'+esc(chord)+'</b>'+svg+'</svg><small>6 → 1번 줄</small></div>'}
function openSheet(s){stopMetro();current=JSON.parse(JSON.stringify(s));transpose=0;$('capo').value='0';$('bpm').value=s.bpm||80;$('songTitle').textContent=s.title;$('songArtist').textContent=s.artist;$('timeSig').textContent=s.meter||'4/4';$('sheetSource').textContent=s.audio?'AUDIO ANALYSIS · ESTIMATED CHORDS':'CHORD SHEET · EASY ARRANGEMENT';$('sheetNote').textContent=s.audio?'음높이 분포로 추정한 장·단조 코드입니다. 보컬·드럼·전위화음·7th 코드 등은 정확도가 낮을 수 있습니다.':'멜로디 없이 코드를 따라 연주하는 쉬운 편곡입니다. 각 칸은 한 마디이며 원곡·특정 음반의 채보가 아닙니다.';$('audioWrap').hidden=!s.audio;$('audio').pause();if(s.audio&&s.id===window.activeAudioId&&objectUrl)$('audio').src=objectUrl;else if(s.audio){$('audio').removeAttribute('src');$('sheetNote').textContent+=' 저장된 악보에는 음원 파일이 포함되지 않습니다.'}renderSheet();$('sheet').hidden=false;$('sheet').scrollIntoView({behavior:'smooth',block:'start'})}
function renderSheet(){if(!current)return;const amount=transpose-Number($('capo').value);$('key').textContent=shift(current.key,transpose);const unique=[...new Set(current.sections.flatMap(s=>s[1].flatMap(c=>c.split(' '))).map(c=>shift(c,amount)))];$('chordDiagrams').innerHTML=unique.filter(c=>c!=='N.C.').map(diagram).join('');$('bars').replaceChildren();let idx=0;current.sections.forEach(([name,bars])=>{const section=document.createElement('div');section.className='bar-section';section.innerHTML='<h3>'+esc(name)+'</h3><div class="bar-grid"></div>';bars.forEach(c=>{const b=document.createElement(current.audio?'button':'div');b.className='bar';b.dataset.index=idx;const time=current.times?.[idx];b.innerHTML='<small>'+(current.audio?format(time):String(idx+1).padStart(2,'0'))+'</small>'+c.split(' ').map(v=>'<span>'+esc(v==='N.C.'?v:shift(v,amount))+'</span>').join('');if(current.audio)b.onclick=()=>{$('audio').currentTime=time||0;$('audio').play().catch(()=>{})};section.querySelector('.bar-grid').append(b);idx++});$('bars').append(section)});$('saveBtn').textContent=saved.some(s=>s.id===current.id)?'♥ 저장됨':'♡ 저장'}
function format(s){return Math.floor((s||0)/60)+':'+String(Math.floor((s||0)%60)).padStart(2,'0')}
function stopMetro(){clearInterval(metroTimer);metroTimer=null;$('metro').textContent='▷ 메트로놈'}
function tick(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=880;g.gain.setValueAtTime(.12,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.07);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.08)}
function setNav(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter))}
$('searchForm').onsubmit=e=>{e.preventDefault();search()};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('query').value=b.dataset.query;search()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{searchSeq++;filter=b.dataset.filter;setNav();status('');list()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{searchSeq++;view=b.dataset.view;filter='all';query='';$('query').value='';setNav();status('');list()});$('uploadBtn').onclick=$('uploadNav').onclick=()=>$('audioFile').click();$('dialogClose').onclick=()=>$('dialog').close();$('closeSheet').onclick=()=>{$('sheet').hidden=true;$('audio').pause();stopMetro()};$('up').onclick=()=>{transpose++;renderSheet()};$('down').onclick=()=>{transpose--;renderSheet()};$('capo').onchange=renderSheet;$('printBtn').onclick=()=>window.print();$('saveBtn').onclick=()=>{if(!current)return;const i=saved.findIndex(s=>s.id===current.id);if(i>=0)saved.splice(i,1);else saved.push(current);persist();renderSheet();if(view==='saved')list()};$('metro').onclick=()=>{if(metroTimer){stopMetro();return}const bpm=Number($('bpm').value);if(!Number.isFinite(bpm)||bpm<30||bpm>240){$('bpm').value=80;return}tick();metroTimer=setInterval(tick,60000/bpm);$('metro').textContent='■ 메트로놈 정지'};$('bpm').onchange=stopMetro;
$('audio').ontimeupdate=()=>{if(!current?.audio)return;let i=current.times.findIndex((t,k)=>$('audio').currentTime>=t&&($('audio').currentTime<(current.times[k+1]??Infinity)));document.querySelectorAll('.bar').forEach(b=>b.classList.toggle('active',Number(b.dataset.index)===i))};
$('help').onclick=()=>modal('<div class="eyebrow">WELCOME TO CHORDROOM</div><h2>오늘의 첫 코드를 잡아보세요.</h2><p><b>노래 검색</b><br>수록된 전통곡은 검색 후 바로 코드악보를 엽니다. 일반 곡은 Apple의 음원 검색을 이용하며, 악보가 미등록된 곡은 외부 코드 검색으로 연결됩니다.</p><p><b>YouTube · YouTube Music 링크</b><br>영상 링크를 붙여넣으면 영상 확인과 Chordify 검색을 엽니다. 유튜브 음원 자체를 추출·분석하지는 않습니다.</p><p><b>직접 가진 음원</b><br>MP3·WAV 등 100MB / 10분 이하 파일의 장·단조 코드를 브라우저에서 추정합니다. 파일은 서버에 전송하지 않습니다.</p><p><b>내 악보</b><br>조옮김, 카포, 운지표, 메트로놈, 인쇄를 지원합니다. 저장한 악보는 이 기기의 브라우저에 보관됩니다.</p>');
function fft(re,im){const n=re.length;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]]}}for(let len=2;len<=n;len<<=1){const a=-2*Math.PI/len,wr=Math.cos(a),wi=Math.sin(a);for(let i=0;i<n;i+=len){let ur=1,ui=0;for(let j=0;j<len/2;j++){const k=i+j,l=k+len/2,vr=re[l]*ur-im[l]*ui,vi=re[l]*ui+im[l]*ur;re[l]=re[k]-vr;im[l]=im[k]-vi;re[k]+=vr;im[k]+=vi;const t=ur*wr-ui*wi;ui=ur*wi+ui*wr;ur=t}}}}
function detect(samples,sr,start){const n=16384,re=new Float64Array(n),im=new Float64Array(n);let energy=0;for(let i=0;i<n;i++){const v=samples[start+i]||0;energy+=v*v;re[i]=v*(.5-.5*Math.cos(2*Math.PI*i/(n-1)))}if(energy/n<.00001)return 'N.C.';fft(re,im);const chroma=new Float64Array(12);for(let k=Math.ceil(75*n/sr);k<Math.min(n/2,1800*n/sr);k++){const f=k*sr/n,midi=69+12*Math.log2(f/440),nearest=Math.round(midi);const mag=Math.sqrt(re[k]*re[k]+im[k]*im[k]);chroma[(nearest%12+12)%12]+=mag/Math.sqrt(f)}const sum=chroma.reduce((a,b)=>a+b,0);if(sum<.001)return 'N.C.';let best=-Infinity,result='N.C.';for(let root=0;root<12;root++){for(const minor of [false,true]){const third=(root+(minor?3:4))%12,fifth=(root+7)%12;let score=(chroma[root]*1.15+chroma[third]+chroma[fifth])/(sum);score-=chroma[(root+(minor?4:3))%12]/sum*.5;if(score>best){best=score;result=notes[root]+(minor?'m':'')}}}return result}
async function analyzeAudioFile(file,metadata={}){if(!file||analyzing)return;if(file.size>100*1024*1024){status('100MB 이하 음원을 선택해주세요.');return}analyzing=true;$('uploadBtn').disabled=true;status('음원을 여는 중입니다…');let ctx;try{ctx=new(window.AudioContext||window.webkitAudioContext)();const buf=await ctx.decodeAudioData(await file.arrayBuffer());if(buf.duration>600)throw new Error('10분 이하 음원을 선택해주세요.');if(buf.duration<1)throw new Error('1초 이상 음원을 선택해주세요.');const samples=new Float32Array(buf.length);for(let ch=0;ch<buf.numberOfChannels;ch++){const data=buf.getChannelData(ch);for(let i=0;i<data.length;i++)samples[i]+=data[i]/buf.numberOfChannels}const chords=[],times=[];const step=2;for(let t=0;t<buf.duration;t+=step){const votes={};for(const offset of [0,.5,1]){if(t+offset>=buf.duration)continue;const c=detect(samples,buf.sampleRate,Math.floor((t+offset)*buf.sampleRate));votes[c]=(votes[c]||0)+1}chords.push(Object.keys(votes).sort((a,b)=>votes[b]-votes[a])[0]||'N.C.');times.push(t);if(chords.length%8===0){status('코드 분석 중 · '+Math.min(99,Math.round(t/buf.duration*100))+'%');await new Promise(r=>setTimeout(r,0))}}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);const id='audio-'+Date.now();window.activeAudioId=id;const sections=[];for(let i=0;i<chords.length;i+=16)sections.push([format(times[i])+' · 각 칸 2초',chords.slice(i,i+16)]);openSheet({id,title:metadata.title||file.name.replace(/\.[^.]+$/,''),artist:metadata.artist||'내 음원 · 자동 코드 추정',audio:true,duration:buf.duration,key:chords.find(c=>c!=='N.C.')||'C',bpm:80,meter:'시간 기준',times,sections});status('음원 분석 완료 · 코드 '+chords.length+'구간. 결과는 추정값이며, 템포 80은 메트로놈의 기본 설정입니다.')}catch(err){status(err.message?.includes('선택')?err.message:'이 음원을 열지 못했습니다. 브라우저가 지원하는 MP3·WAV 파일을 선택해주세요.')}finally{if(ctx)ctx.close();analyzing=false;$('uploadBtn').disabled=false}};
$('audioFile').onchange=e=>{const file=e.target.files[0];e.target.value='';return analyzeAudioFile(file)};
